package com.portfolio.features.resume.controller;
import com.portfolio.common.api.ApiResponse; import com.portfolio.features.resume.dto.request.ResumeImportRequest; import com.portfolio.features.resume.dto.response.ResumeImportResponse; import com.portfolio.features.resume.service.ResumeImportService; import com.portfolio.features.user.service.UserService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequiredArgsConstructor public class ResumeImportController { private final ResumeImportService service; private final UserService users; @PostMapping("/api/resume/import") public ApiResponse<ResumeImportResponse> importResume(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody ResumeImportRequest request){return ApiResponse.success("Resume data imported successfully.",service.importResume(users.synchronize(jwt),request));}}
